scripts.script:
/* T-6-4 查①:org.flywaydb 裸 import 白名单(D15 护栏①)。
   场景与为什么:serial 仓 jSerialComm 被 22 仓直接 import 的先例证明「库放 trunk、
   消费者裸 import」会把引擎演进锁死在全仓;flyway 走窄门面(片5 T-5-1),唯一合法方
   =ecat-db-migration 仓,其余仓出现 import 即依赖面越界,构建期拦截。 */

// ---- 白名单:每元素一个 artifactId,整仓豁免;增删必须走本仓 commit 留痕(理由+登记日期写行尾注释) ----
whitelist = new String[] {
    "integration-ecat-db-migration",  // D15 护栏①唯一合法方,随片5 T-5-1 实施登记(2026-10-04)
};

selfId = project.getArtifactId();
for (def i = 0; i < whitelist.length; i = i + 1) {
    if (whitelist[i].equals(selfId)) { return; }   // 白名单仓整查豁免
}

hits = new java.util.ArrayList();
scanImports(new java.io.File(project.getBasedir(), "src/main/java"), hits);
scanImports(new java.io.File(project.getBasedir(), "src/test/java"), hits);

if (hits.isEmpty()) { return; }

// ---- 输出:RED 明细+摘要,抛错判构建失败(gmavenplus 忽略脚本返回值,RED 契约=异常) ----
lines = new java.util.ArrayList();
for (def i = 0; i < hits.size(); i = i + 1) {
    lines.add("[ECAT-LINT][T6-4-1][RED] " + selfId + " | " + hits.get(i)
        + " | org.flywaydb 裸 import(D15 护栏①:唯一合法方=ecat-db-migration 窄门面仓;"
        + "消费者一律走门面,修复=删 import 改调门面)");
}
emitReport(lines, "T6-4-1", hits.size(), 0);
throw new Exception("[ECAT-LINT][T6-4-1] 构建判失败:白名单外 org.flywaydb 裸 import,明细见上方行与 target/ecat-lint-report.txt");

// ---- 方法区(无类型方法签名;类名全限定) ----
void scanImports(dir, out) {
    if (dir == null || !dir.isDirectory()) { return; }
    def children = dir.listFiles();
    if (children == null) { return; }
    for (def i = 0; i < children.length; i = i + 1) {
        def f = children[i];
        if (f.isDirectory()) { scanImports(f, out); }
        else if (f.getName().endsWith(".java")) {
            def br = null;
            try {
                br = new java.io.BufferedReader(new java.io.FileReader(f));
                def line = br.readLine(); def ln = 0;
                while (line != null) {
                    ln = ln + 1;
                    def t = line.trim();
                    if (t.startsWith("import org.flywaydb.") || t.startsWith("import static org.flywaydb.")) {
                        def rel = project.getBasedir().toPath().relativize(f.toPath()).toString().replace('\\', '/');
                        out.add(rel + ":" + ln);
                    }
                    line = br.readLine();
                }
            } finally {
                if (br != null) { try { br.close(); } catch (java.io.IOException e) { } }
            }
        }
    }
}

void emitReport(lines, checkId, red, warn) {
    for (def i = 0; i < lines.size(); i = i + 1) { System.out.println(lines.get(i)); }
    def summary = "[ECAT-LINT][摘要] artifactId=" + project.getArtifactId() + " RED=" + red + " WARN=" + warn;
    System.out.println(summary);
    def w = null;
    try {
        def reportFile = new java.io.File(project.getBuild().getDirectory(), "ecat-lint-report.txt");
        reportFile.getParentFile().mkdirs();   // validate 期 target/ 尚未物化(首跑实证),不建目录则 FileWriter 必炸
        w = new java.io.BufferedWriter(new java.io.FileWriter(reportFile));
        for (def j = 0; j < lines.size(); j = j + 1) { w.write(lines.get(j)); w.newLine(); }
        w.write(summary); w.newLine();
    } finally {
        if (w != null) { try { w.close(); } catch (java.io.IOException e) { } }
    }
}

/* T-6-4 查②:SQL 路径规范(D28 §0.5)。
   场景与为什么:全仓 sql 一度散落(9 件域主旧 resources/sql+ruoyi/sql 9 件),
   「哪份是真相源」无从回答;立法后唯一合法路径=db/migration-<domain>/,游离 sql
   在构建期即红。白名单=T-5-8 清零前的过渡登记,清零时删空(只减不增)。 */

// ---- 过渡白名单:每元素="<artifactId>|<仓内相对路径>" 双键(防同相对路径跨仓误放),
//      行尾注释=理由+时限;增删走本仓 commit 留痕,只减不增 ----
// T-5-8 清零已落地(2026-10-04 直读游离 sql=0),按「清零后删空」现为空集
whitelist = new String[] {
};

selfId = project.getArtifactId();
violations = new java.util.ArrayList();
collectSql(project.getBasedir(), "", violations);

lines = new java.util.ArrayList();
for (def i = 0; i < violations.size(); i = i + 1) {
    rel = (String) violations.get(i);
    if (isLegalPath(rel)) { continue; }   // 合法路径不进违规表(先判法条,再判白名单;合法路径文件无需登记)
    if (isWhitelisted(selfId, rel)) { continue; }
    lines.add("[ECAT-LINT][T6-4-2][RED] " + selfId + " | " + rel
        + " | SQL 游离于 db/migration-*/ 之外(D28 §0.5:唯一合法=src/main/resources/db/migration-<domain>/;"
        + "修复=迁入对应域 migration 目录并走 T-5-8 对账纪律)");
}
if (lines.isEmpty()) { return; }
emitReport(lines, "T6-4-2", lines.size(), 0);
throw new Exception("[ECAT-LINT][T6-4-2] 构建判失败:白名单外 SQL 游离于 db/migration-*/ 之外,明细见上方行与 target/ecat-lint-report.txt");

// ---- 方法区(无类型签名;类名全限定) ----
void collectSql(dir, relPrefix, out) {
    if (dir == null || !dir.isDirectory()) { return; }
    def name = dir.getName();
    if (name.equals("target") || name.equals("node_modules")) { return; }   // 构建产物与前端依赖树不扫
    def children = dir.listFiles();
    if (children == null) { return; }
    for (def i = 0; i < children.length; i = i + 1) {
        def f = children[i];
        def rel = relPrefix.equals("") ? f.getName() : relPrefix + "/" + f.getName();
        if (f.isDirectory()) { collectSql(f, rel, out); }
        else if (f.getName().endsWith(".sql")) { out.add(rel); }
    }
}

boolean isLegalPath(rel) {
    def seg = rel.replace('\\', '/').split("/");
    for (def i = 0; i + 1 < seg.length; i = i + 1) {
        if (seg[i].equals("db") && seg[i + 1].startsWith("migration-") && seg[i + 1].length() > 10) { return true; }
    }
    return false;
}

boolean isWhitelisted(artifactId, rel) {
    def key = artifactId + "|" + rel.replace('\\', '/');
    for (def i = 0; i < whitelist.length; i = i + 1) {
        if (whitelist[i].equals(key)) { return true; }
    }
    return false;
}

void emitReport(lines, checkId, red, warn) {
    for (def i = 0; i < lines.size(); i = i + 1) { System.out.println(lines.get(i)); }
    def summary = "[ECAT-LINT][摘要] artifactId=" + project.getArtifactId() + " RED=" + red + " WARN=" + warn;
    System.out.println(summary);
    def w = null;
    try {
        def reportFile = new java.io.File(project.getBuild().getDirectory(), "ecat-lint-report.txt");
        reportFile.getParentFile().mkdirs();   // validate 期 target/ 尚未物化(首跑实证),不建目录则 FileWriter 必炸
        w = new java.io.BufferedWriter(new java.io.FileWriter(reportFile));
        for (def j = 0; j < lines.size(); j = j + 1) { w.write(lines.get(j)); w.newLine(); }
        w.write(summary); w.newLine();
    } finally {
        if (w != null) { try { w.close(); } catch (java.io.IOException e) { } }
    }
}

/* T-6-4 查③:db 约定块缺声明(片5 T-5-6 联动)。
   场景与为什么:db 约定块(T-5-6 契约,声明本仓持有哪些域的迁移账本)是升级链
   dump 范围/建库单轨的机器可读依据;持有 mapper 或迁移目录的仓却不声明=账本悬空。
   现值触发面仓全数声明完毕(T-5-6 存量补齐,2026-10-04 复核),当前常态=零输出;
   strict 属性翻 true 后升红(生产翻转只走 parent 属性行,git 可审)。 */

strict = "true".equals(project.getProperties().getProperty("ecat.lint.dbblock.strict", "false"));
resDir = new java.io.File(project.getBasedir(), "src/main/resources");
hasMapper = dirContainsXml(new java.io.File(resDir, "mapper"));
hasMigration = dbDirHasMigration(new java.io.File(resDir, "db"));

if (!hasMapper && !hasMigration) { return; }

cfg = new java.io.File(resDir, "ecat-config.yml");
hasDb = false;
reason = "ecat-config.yml 文件缺失";
if (cfg.isFile()) {
    reason = "缺顶层 db: 块";
    br = null;
    try {
        br = new java.io.BufferedReader(new java.io.FileReader(cfg));
        line = br.readLine();
        while (line != null) {
            p = java.util.regex.Pattern.compile("^db\\s*:").matcher(line);
            if (p.find()) { hasDb = true; break; }
            line = br.readLine();
        }
    } finally {
        if (br != null) { try { br.close(); } catch (java.io.IOException e) { } }
    }
}
if (hasDb) { return; }

sev = strict ? "RED" : "WARN";
lines = new java.util.ArrayList();
lines.add("[ECAT-LINT][T6-4-3][" + sev + "] " + project.getArtifactId()
    + " | src/main/resources/ecat-config.yml | " + reason
    + "(触发:持有 mapper=" + hasMapper + " / db/migration-*=" + hasMigration
    + ";db 约定块契约=片5 T-5-6,契约落地前只警告" + (strict ? ",现已 strict 升红" : "")
    + ";修复=按 T-5-6 契约补 db: 块)");
emitReport(lines, "T6-4-3", strict ? 1 : 0, strict ? 0 : 1);
if (strict) { throw new Exception("[ECAT-LINT][T6-4-3] 构建判失败:strict 模式下 db 约定块缺失,明细见上方行与 target/ecat-lint-report.txt"); }

// ---- 方法区(无类型签名) ----
boolean dirContainsXml(dir) {
    if (dir == null || !dir.isDirectory()) { return false; }
    def children = dir.listFiles();
    if (children == null) { return false; }
    for (def i = 0; i < children.length; i = i + 1) {
        def f = children[i];
        if (f.isDirectory()) { if (dirContainsXml(f)) { return true; } }
        else if (f.getName().endsWith(".xml")) { return true; }
    }
    return false;
}

boolean dbDirHasMigration(dbDir) {
    if (dbDir == null || !dbDir.isDirectory()) { return false; }
    def children = dbDir.listFiles();
    if (children == null) { return false; }
    for (def i = 0; i < children.length; i = i + 1) {
        def d = children[i];
        if (d.isDirectory() && d.getName().startsWith("migration-") && d.getName().length() > 10) { return true; }
    }
    return false;
}

void emitReport(lines, checkId, red, warn) {
    for (def i = 0; i < lines.size(); i = i + 1) { System.out.println(lines.get(i)); }
    def summary = "[ECAT-LINT][摘要] artifactId=" + project.getArtifactId() + " RED=" + red + " WARN=" + warn;
    System.out.println(summary);
    def w = null;
    try {
        def reportFile = new java.io.File(project.getBuild().getDirectory(), "ecat-lint-report.txt");
        reportFile.getParentFile().mkdirs();   // validate 期 target/ 尚未物化(首跑实证),不建目录则 FileWriter 必炸
        w = new java.io.BufferedWriter(new java.io.FileWriter(reportFile));
        for (def j = 0; j < lines.size(); j = j + 1) { w.write(lines.get(j)); w.newLine(); }
        w.write(summary); w.newLine();
    } finally {
        if (w != null) { try { w.close(); } catch (java.io.IOException e) { } }
    }
}

/* T-6-6 查④:requires_core 构建期对齐(D26 P3-4)。
   场景与为什么:重刻刷版本(片7)只刷 pom 不刷 config(或反向)的仓,运行时 boot 门
   才拒载(片3 T-3-2)——问题暴露在设备上;本门在构建期查同一份两源声明的一致性,
   「两源都有值时的一致性」归构建期,缺失侧归片3 运行时(卡分工)。判定器反射绑定
   core VersionRange=与运行时门同一实现,零第二语义。RED 契约=抛异常(gmavenplus
   忽略脚本返回值,同查①②③)。 */

selfId = project.getArtifactId();

// ---- 过渡白名单:每元素一个 artifactId,整仓豁免;行尾注释=理由+清理条件,只减不增 ----
whitelist = new String[] {
    "integration-ecat-db-migration",  // T-5-1 新纪元仓:requires_core=^4.0.0(拍板)对 pom 现值 3.1.0 的片7 前过渡;片7 重刻落地后移除,只减不增(2026-10-04 lead 裁案A;运行时装载语义不变,core 3.x 仍恒红拒载)
};
for (def i = 0; i < whitelist.length; i = i + 1) {
    if (whitelist[i].equals(selfId)) { return; }   // 白名单仓整查豁免
}

if ("pom".equals(project.getPackaging())) { return; }   // 触发面谓词:pom 打包模块(父/聚合)非集成件,永不入运行时门管辖,不发假 WARN(同查③触发面模式;lead 裁 2026-10-04;99 子仓全 jar 实证零执法损失)

cfg = new java.io.File(project.getBasedir(), "src/main/resources/ecat-config.yml");
if (!cfg.isFile()) {   // W1:config 缺失侧
    warnLines = new java.util.ArrayList();
    warnLines.add("[ECAT-LINT][T6-6][WARN] " + selfId
        + " | ecat-config.yml 缺失 | 缺失方归片3 T-3-2 运行时门,构建期不执法");
    emitReport(warnLines, "T6-6", 0, 1);
    return;
}

// ---- 源②:requires_core 行语法提取(注释行跳过;>1 行命中=声明歧义红,禁猜取哪行) ----
constraint = null; lineNo = 0; hitCount = 0;
br = null;
try {
    br = new java.io.BufferedReader(new java.io.FileReader(cfg));
    line = br.readLine(); ln = 0;
    while (line != null) {
        ln = ln + 1;
        if (!line.trim().startsWith("#")) {
            m = java.util.regex.Pattern.compile('^requires_core\\s*:\\s*(.+?)\\s*$').matcher(line);   // 单引号=groovy 纯 String(双引号是 GString,$" 非法插值,词法即炸)
            if (m.find()) { hitCount = hitCount + 1; constraint = m.group(1); lineNo = ln; }
        }
        line = br.readLine();
    }
} finally {
    if (br != null) { try { br.close(); } catch (java.io.IOException e) { } }
}
if (hitCount == 0) {   // W1:约束缺失侧
    warnLines = new java.util.ArrayList();
    warnLines.add("[ECAT-LINT][T6-6][WARN] " + selfId
        + " | src/main/resources/ecat-config.yml | 缺 requires_core 声明 | 缺失方归片3 T-3-2 运行时门,构建期不执法");
    emitReport(warnLines, "T6-6", 0, 1);
    return;
}
if (hitCount > 1) {    // R1:声明歧义
    redLines = new java.util.ArrayList();
    redLines.add("[ECAT-LINT][T6-6][RED] " + selfId
        + " | src/main/resources/ecat-config.yml:" + lineNo
        + " | requires_core 声明歧义(命中 " + hitCount + " 行,禁猜取哪行)");
    emitReport(redLines, "T6-6", 1, 0);
    throw new Exception("[ECAT-LINT][T6-6] 构建判失败:requires_core 声明歧义,明细见上方行与 target/ecat-lint-report.txt");
}
if (constraint.startsWith("\"") && constraint.endsWith("\"") && constraint.length() >= 2) {
    constraint = constraint.substring(1, constraint.length() - 1);   // 剥成对双引号(container 形态)
}

// ---- 源①:解析后 ecat-core 版本(Maven 已消解字面量/属性/depMgmt 的编译真值) ----
coreArt = null;
arts = project.getArtifacts();
artIt = arts.iterator();
while (artIt.hasNext()) {
    a = artIt.next();
    if ("ecat-core".equals(a.getArtifactId())) { coreArt = a; }
}
if (coreArt == null) {   // W2:pom 无 core 依赖侧
    warnLines = new java.util.ArrayList();
    warnLines.add("[ECAT-LINT][T6-6][WARN] " + selfId
        + " | pom 无 ecat-core 依赖 | 缺失方归片3 T-3-2 运行时门,构建期不执法");
    emitReport(warnLines, "T6-6", 0, 1);
    return;
}
coreVersion = coreArt.getVersion();

// ---- 判定:反射桥(独立 URLClassLoader 不经插件 classpath=自举成立条件;
//      invoke 包装语义:目标异常必被 InvocationTargetException 包装,getCause() 解包后分流,
//      直接 catch IllegalArgumentException=死分支) ----
try {
    loader = new java.net.URLClassLoader(new java.net.URL[] { coreArt.getFile().toURI().toURL() }, (java.lang.ClassLoader) null);   // cast 消歧(URLClassLoader 双重载,groovy 对 null 字面量动态分派选不了)
    clsV = Class.forName("com.ecat.core.Version.Version", true, loader);
    clsR = Class.forName("com.ecat.core.Version.VersionRange", true, loader);
    version = clsV.getMethod("parse", new Class[] { String.class }).invoke(null, new Object[] { coreVersion });
    range   = clsR.getMethod("parse", new Class[] { String.class }).invoke(null, new Object[] { constraint });
    ok = (Boolean) clsR.getMethod("satisfies", new Class[] { clsV }).invoke(range, new Object[] { version });
} catch (java.lang.ClassNotFoundException cnfe) {   // R5:桥绑定面漂移
    redLines = new java.util.ArrayList();
    redLines.add("[ECAT-LINT][T6-6][RED] " + selfId + " | 桥绑定面漂移:core 类不可达("
        + cnfe.getMessage() + ") | 修复=核对绑定三签名 Version.parse/VersionRange.parse/VersionRange.satisfies(core 版本变更/归一改签名时改桥三行)");
    emitReport(redLines, "T6-6", 1, 0);
    throw new Exception("[ECAT-LINT][T6-6] 构建判失败:桥绑定面漂移,core 类不可达,明细见上方行与 target/ecat-lint-report.txt");
} catch (java.lang.reflect.InvocationTargetException ite) {
    cause = ite.getCause();   // invoke 包装语义:目标异常在此,解包后分流
    if (cause instanceof IllegalArgumentException) {   // R3:Version/VersionRange parse 的非法输入
        redLines = new java.util.ArrayList();
        redLines.add("[ECAT-LINT][T6-6][RED] " + selfId + " | 约束/版本解析失败:"
            + cause.getMessage() + "(经 invoke 解包;与片3 运行时门同口径:解析不了=明确失败)");
        emitReport(redLines, "T6-6", 1, 0);
        throw new Exception("[ECAT-LINT][T6-6] 构建判失败:约束/版本解析失败,明细见上方行与 target/ecat-lint-report.txt");
    }
    redLines = new java.util.ArrayList();   // R6:非预期目标异常,照样红+带诊断,不吞
    redLines.add("[ECAT-LINT][T6-6][RED] " + selfId + " | 反射调用目标异常:"
        + cause.getClass().getName() + ":" + cause.getMessage());
    emitReport(redLines, "T6-6", 1, 0);
    throw new Exception("[ECAT-LINT][T6-6] 构建判失败:反射调用目标异常,明细见上方行与 target/ecat-lint-report.txt");
}

if (ok.booleanValue()) { return; }   // G

redLines = new java.util.ArrayList();   // R2:不满足
redLines.add("[ECAT-LINT][T6-6][RED] " + selfId + " | pom-ecat-core=" + coreVersion
    + " vs requires_core=" + constraint + "(src/main/resources/ecat-config.yml:" + lineNo + ") | 不满足("
    + semanticsOf(constraint) + ") | 修复=两源同步(重刻期=片7 归一清单动作;日常=提版本或改约束,二者取真实意图)");
emitReport(redLines, "T6-6", 1, 0);
throw new Exception("[ECAT-LINT][T6-6] 构建判失败:pom-ecat-core 版本不满足 requires_core 约束,明细见上方行与 target/ecat-lint-report.txt");

// ---- 方法区(无类型签名;emitReport 逐字同查①②③现值;semanticsOf 仅拼人话,判定唯一来源=VersionRange 返回值,两处不得互串) ----
String semanticsOf(c) {   // ^/~ 形态机械展开区间,人话辅助不参与判定
    if (c.startsWith("^")) { def b = c.substring(1); return "[>=" + b + ",<" + nextMajor(b) + ")"; }
    if (c.startsWith("~")) { def b = c.substring(1); return "[>=" + b + ",<" + nextMinor(b) + ")"; }
    return c;
}
String nextMajor(b) { def parts = b.split("\\."); return (Integer.parseInt(parts[0]) + 1) + ".0.0"; }
String nextMinor(b) { def parts = b.split("\\."); return parts[0] + "." + (Integer.parseInt(parts[1]) + 1) + ".0"; }

void emitReport(lines, checkId, red, warn) {
    for (def i = 0; i < lines.size(); i = i + 1) { System.out.println(lines.get(i)); }
    def summary = "[ECAT-LINT][摘要] artifactId=" + project.getArtifactId() + " RED=" + red + " WARN=" + warn;
    System.out.println(summary);
    def w = null;
    try {
        def reportFile = new java.io.File(project.getBuild().getDirectory(), "ecat-lint-report.txt");
        reportFile.getParentFile().mkdirs();   // validate 期 target/ 尚未物化(首跑实证),不建目录则 FileWriter 必炸
        w = new java.io.BufferedWriter(new java.io.FileWriter(reportFile));
        for (def j = 0; j < lines.size(); j = j + 1) { w.write(lines.get(j)); w.newLine(); }
        w.write(summary); w.newLine();
    } finally {
        if (w != null) { try { w.close(); } catch (java.io.IOException e) { } }
    }
}

/* 查⑤:API 兼容门(japicmp)窗态显式分离(2026-10-04 D63③,japicmp 基线缺口可本地半边)。
   场景与为什么:门 skip 窗态(-Decat.japicmp.skip=true,基线收集窗/登记逃生合法)在插件侧
   只有一行 [INFO] japicmp skipped.,绿构建不带任何「门未执法」醒目标记——消费方以
   BUILD SUCCESS 为据会误读成门通过(T-1-5 同窗实证:skip 完成 install,门态只能靠
   人读交单报告自觉披露)。本查把门态三态在报告面显式分离:
   ①真比对=日志见 japicmp:cmp 执行+target/japicmp/ 报告三件(diff/md/xml);
   ②基线解析失败=[ERROR] Could not find previous version=构建红(fail-closed,
     ignoreMissingOldVersion=false 有牙,勿与 skip 混淆、勿删);
   ③skip 窗态=本查横幅(唯一曾静默的态,消灭之):放行不拦构建,但 [ECAT-GATE][WINDOW]
   醒目横幅+报告双通道,归因证据不得引用本构建为门绿。
   GREEN 契约=skip 非 true 时零输出零落盘(同查①②③绿跑纪律)。 */

skipVal = session.getUserProperties().getProperty("ecat.japicmp.skip");   // CLI -D 域(窗态 flag 实际落点)
if (skipVal == null) { skipVal = session.getSystemProperties().getProperty("ecat.japicmp.skip"); }   // CLI 预留集落点
if (skipVal == null) { skipVal = project.getProperties().getProperty("ecat.japicmp.skip"); }         // pom <properties> 域(字面量/profile)
if (!"true".equals(skipVal)) { return; }   // 非窗态:零输出零落盘

lines = new java.util.ArrayList();
lines.add("[ECAT-GATE][WINDOW][WARN] " + project.getArtifactId()
    + " | API 兼容门(japicmp)本构建 skip=true:零执法,BUILD SUCCESS≠门通过");
lines.add("[ECAT-GATE][WINDOW] 门态判定口径:真比对=日志 japicmp:cmp 执行+target/japicmp/ 报告三件;"
    + "基线解析失败=[ERROR] Could not find previous version=构建红(fail-closed,非 skip);"
    + "本构建=skip 窗态(基线收集窗/登记逃生),API 兼容零执法");
emitReport(lines, "GATE-WINDOW", 0, 1);

// ---- 方法区(无类型签名;emitReport 逐字同查①②③④现值) ----
void emitReport(lines, checkId, red, warn) {
    for (def i = 0; i < lines.size(); i = i + 1) { System.out.println(lines.get(i)); }
    def summary = "[ECAT-LINT][摘要] artifactId=" + project.getArtifactId() + " RED=" + red + " WARN=" + warn;
    System.out.println(summary);
    def w = null;
    try {
        def reportFile = new java.io.File(project.getBuild().getDirectory(), "ecat-lint-report.txt");
        reportFile.getParentFile().mkdirs();   // validate 期 target/ 尚未物化(首跑实证),不建目录则 FileWriter 必炸
        w = new java.io.BufferedWriter(new java.io.FileWriter(reportFile));
        for (def j = 0; j < lines.size(); j = j + 1) { w.write(lines.get(j)); w.newLine(); }
        w.write(summary); w.newLine();
    } finally {
        if (w != null) { try { w.close(); } catch (java.io.IOException e) { } }
    }
}
